using System;using System.IO;using System.IO.Compression;
namespace WhiteDragon {
// This replaces only recognisable pixels of the old static book prop and
// composites a matching plate behind foreground pixels; source media is intact.
public static class BookStackConsistency {
 const int X=398,Y=304,W=65,H=31;
 static readonly byte[] Reference=Unpack(""), Plate=Unpack("");
 static byte[] Unpack(string value){var data=Convert.FromBase64String(value);var result=new byte[W*H*4];using(var s=new GZipStream(new MemoryStream(data),CompressionMode.Decompress)){int n=0,k;while(n<result.Length&&(k=s.Read(result,n,result.Length-n))>0)n+=k;if(n!=result.Length)throw new InvalidDataException("Invalid book plate");}return result;}
 static double Ease(double v){v=Math.Max(0,Math.Min(1,v));return v*v*(3-2*v);}
 public static void Apply(int row,int index,byte[] pixels){
  if(row!=18&&row!=19)return; // New row25 already retains its own source book stack.
  double protect=row==25?Ease((index-84)/12.0)*(1-Ease((index-168)/18.0)):0;
  for(int y=0;y<H;y++)for(int x=0;x<W;x++){
   int j=(y*W+x)*4,k=((y+Y)*640+x+X)*4,oldA=Reference[j+3],baseA=Plate[j+3];if(oldA<=3&&baseA==0)continue;
   int a=pixels[k+3],b=pixels[k],g=pixels[k+1],r=pixels[k+2];
   bool skin=a>=245&&r-g>=12&&r-b>=12;
   double remove=0;if(oldA>3&&x+X>=406&&!skin){int d=0;for(int c=0;c<4;c++)d=Math.Max(d,Math.Abs(pixels[k+c]-Reference[j+c]));remove=Ease((16-d)/12.0);if(y+Y<315)remove*=1-protect;}
   double keep=1-remove;int fa=(int)Math.Round(a*keep);double behind=(255-fa)/255.0;
   pixels[k]=(byte)Math.Min(255,Math.Round(b*keep+Plate[j]*behind));
   pixels[k+1]=(byte)Math.Min(255,Math.Round(g*keep+Plate[j+1]*behind));
   pixels[k+2]=(byte)Math.Min(255,Math.Round(r*keep+Plate[j+2]*behind));
   pixels[k+3]=(byte)Math.Min(255,Math.Round(fa+baseA*behind));
  }
 }
}
}